package com.puppy.model;

import com.puppy.enums.MessageRole;

import java.time.Instant;
import java.util.Objects;

/**
 * One persisted chat message.
 *
 * @param id             random UUID string, generated by the service layer
 * @param conversationId owning conversation
 * @param role           user or assistant
 * @param content        visible message text
 * @param createdAt      UTC instant the message was saved
 */
public record ChatMessage(
        String id,
        String conversationId,
        MessageRole role,
        String content,
        Instant createdAt
) {

    public ChatMessage {
        id = Validate.text(id, "id");
        conversationId = Validate.text(conversationId, "conversationId");
        role = Objects.requireNonNull(role, "role");
        content = Validate.text(content, "content");
        createdAt = Objects.requireNonNull(createdAt, "createdAt");
    }
}
